// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(uint256 firstAmount, uint256 secondAmount) public {
        firstAmount = bound(firstAmount, 0, type(uint256).max);
        secondAmount = bound(secondAmount, 0, type(uint256).max);

        c.AdjustBetAmounts(firstAmount);
        c.AdjustBetAmounts(secondAmount);

        assertTrue(c.currentBetLimit() == secondAmount);
    }
}
